package net.civeira.phylax.feature.identity.tenantconfig.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.tenantconfig.domain.TenantConfig;
import net.civeira.phylax.feature.identity.tenantconfig.domain.valueobject.InvitationExpiryDaysVO;

class InvitationExpiryDaysValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of invitation expiry days of tenant config")
  void test_invitation_expiry_days_value_holder_assign_plain_value() {
    Object holder = new Object();
    InvitationExpiryDaysValueHolder<Object> value = new InvitationExpiryDaysValueHolder<>(holder);
    Assertions.assertSame(holder, value.invitationExpiryDays(1), "Setters must return the holder");
    Assertions.assertTrue(value.getInvitationExpiryDaysValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(1, value.getInvitationExpiryDays().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of invitation expiry days of tenant config")
  void test_invitation_expiry_days_value_holder_assign_value_object() {
    Object holder = new Object();
    InvitationExpiryDaysValueHolder<Object> value = new InvitationExpiryDaysValueHolder<>(holder);
    InvitationExpiryDaysVO vo = InvitationExpiryDaysVO.from(1);
    Assertions.assertFalse(value.getInvitationExpiryDaysValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.invitationExpiryDays(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getInvitationExpiryDaysValue().orElseThrow());
    Assertions.assertSame(holder, value.invitationExpiryDays(Optional.empty()));
    Assertions.assertFalse(value.getInvitationExpiryDaysValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.invitationExpiryDays(Optional.of(vo)));
    Assertions.assertSame(vo, value.getInvitationExpiryDaysValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of invitation expiry days of tenant config against the original")
  void test_invitation_expiry_days_value_holder_read() {
    Object holder = new Object();
    InvitationExpiryDaysValueHolder<Object> value = new InvitationExpiryDaysValueHolder<>(holder);
    InvitationExpiryDaysVO vo = InvitationExpiryDaysVO.from(1);
    InvitationExpiryDaysVO other = InvitationExpiryDaysVO.from(1);
    TenantConfig original = Mockito.mock(TenantConfig.class);
    Mockito.when(original.getInvitationExpiryDaysValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readInvitationExpiryDays(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readInvitationExpiryDays(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.invitationExpiryDays(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readInvitationExpiryDays(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readInvitationExpiryDays(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of invitation expiry days of tenant config")
  void test_invitation_expiry_days_value_holder_unset() {
    Object holder = new Object();
    InvitationExpiryDaysValueHolder<Object> value = new InvitationExpiryDaysValueHolder<>(holder);
    InvitationExpiryDaysVO vo = InvitationExpiryDaysVO.from(1);
    value.invitationExpiryDays(vo);
    Assertions.assertSame(holder,
        value.unsetInvitationExpiryDaysIfMatches("invitationExpiryDays_other"));
    Assertions.assertTrue(value.getInvitationExpiryDaysValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetInvitationExpiryDaysIfMatches("invitationExpiryDays"));
    Assertions.assertFalse(value.getInvitationExpiryDaysValue().isPresent(),
        "The field name must clear the value");
    value.invitationExpiryDays(vo);
    Assertions.assertSame(holder, value.unsetInvitationExpiryDays());
    Assertions.assertFalse(value.getInvitationExpiryDaysValue().isPresent(),
        "Unset must clear the value");
  }
}
